    #[test]
    fn managed_retention_mid_insert_error_rolls_back_and_retries() {
        let scene = Assignment::new();
        let task = running(&scene);
        let contents: u64 = scene
            .member
            .store()
            .connection()
            .query_row("SELECT COUNT(*) FROM result_content", [], |row| row.get(0))
            .unwrap();
        let refs: u64 = scene
            .member
            .store()
            .connection()
            .query_row("SELECT COUNT(*) FROM result_content_refs", [], |row| {
                row.get(0)
            })
            .unwrap();
        std::fs::write(
            scene
                .member
                .view
                .canonical_path
                .to_path_buf()
                .unwrap()
                .join("README.md"),
            b"edited\n",
        )
        .unwrap();
        scene.member.store().connection().execute_batch("CREATE TRIGGER refuse_change_side BEFORE INSERT ON result_content_refs
            WHEN NEW.owner_kind='successor_change' AND NEW.representation='after:README.md'
            AND EXISTS(SELECT 1 FROM result_content_refs WHERE owner_kind='successor_change' AND owner_id=NEW.owner_id AND representation='before:README.md')
            BEGIN SELECT RAISE(ABORT,'injected retention failure'); END;").unwrap();
        assert_eq!(complete(&scene).unwrap_err().code, "INTERNAL_ERROR");
        assert_eq!(scene.member.task_state(task), "running");
        assert_eq!(scene.member.workload_revision(), 0);
        assert!(scene.member.complete_result_bytes(task).is_none());
        assert_eq!(
            scene
                .member
                .store()
                .connection()
                .query_row(
                    "SELECT COUNT(*) FROM result_content_refs WHERE owner_kind='successor_change'",
                    [],
                    |row| row.get::<_, u64>(0)
                )
                .unwrap(),
            0
        );
        assert_eq!(
            writers(&scene.member).load().unwrap().state,
            crate::writer::WriterAuthorityState::Active
        );
        assert_eq!(scene.member.round_state(task), "counted_accepted");
        assert_eq!(
            scene
                .member
                .store()
                .connection()
                .query_row("SELECT COUNT(*) FROM result_content", [], |row| row
                    .get::<_, u64>(0))
                .unwrap(),
            contents
        );
        assert_eq!(
            scene
                .member
                .store()
                .connection()
                .query_row("SELECT COUNT(*) FROM result_content_refs", [], |row| row
                    .get::<_, u64>(0))
                .unwrap(),
            refs
        );
        scene
            .member
            .store()
            .connection()
            .execute_batch("DROP TRIGGER refuse_change_side")
            .unwrap();
        resettle_member_tasks(
            &scene.member.state_root,
            scene.member.member_ref,
            scene.member.owner(),
        )
        .unwrap();
        assert_eq!(result(&scene.member, task).changes.len(), 1);
        assert_eq!(scene.member.workload_revision(), 1);
    }

    #[test]
    fn managed_async_terminal_observes_cleanup_and_active_write_counts() {
        let scene = Assignment::new();
        let first = running(&scene);
        complete(&scene).unwrap();
        let before = scene.member.workload_revision();
        let collected = scene.collect(first).unwrap();
        assert!(collected.disposition.cleanup_pending);
        assert_eq!(
            scene.identity(first).unwrap_err().code,
            "DISPOSITION_NOT_IDLE"
        );
        assert_eq!(scene.member.workload_revision(), before);
        // A later active write belongs to the held guard rather than stale cleanup.
        let second = scene.member.accept_write_task("next-write");
        assert!(!scene.collect(first).unwrap().disposition.cleanup_pending);
        let json: String = scene
            .member
            .store()
            .connection()
            .query_row(
                "SELECT accepted_request_json FROM brokered_task_acceptances WHERE task_id=?1",
                [second.task_ref.to_string()],
                |row| row.get(0),
            )
            .unwrap();
        let mut tampered: Value = serde_json::from_str(&json).unwrap();
        tampered["execution_intent"] = json!("read_only");
        scene
            .member
            .store()
            .connection()
            .execute(
                "UPDATE brokered_task_acceptances SET accepted_request_json=?1 WHERE task_id=?2",
                rusqlite::params![
                    serde_json::to_string(&tampered).unwrap(),
                    second.task_ref.to_string()
                ],
            )
            .unwrap();
        assert!(scene.collect(first).is_err());
        assert!(scene.identity(first).is_err());
        scene
            .member
            .store()
            .connection()
            .execute(
                "UPDATE brokered_task_acceptances SET accepted_request_json='{}',accepted_request_sha256=?1 WHERE task_id=?2",
                rusqlite::params![sha256_hex(b"{}"),second.task_ref.to_string()],
            )
            .unwrap();
        assert!(scene.collect(first).is_err());
        assert!(scene.identity(first).is_err());
    }

    #[test]
    fn managed_collect_and_identity_bind_count_and_quiescence_to_one_snapshot() {
        use std::cell::RefCell;
        use std::rc::Rc;
        for identity in [false, true] {
            for writer_changes in [false, true] {
                let scene = Rc::new(Assignment::new());
                let first = running(&scene);
                complete(&scene).unwrap();
                let second = (!writer_changes).then(|| {
                    scene
                        .member
                        .accept_write_task("active-before-observation")
                        .task_ref
                });
                let counts = Rc::new(RefCell::new(Vec::new()));
                let operation = if identity {
                    "get_managed_delegation_identity"
                } else {
                    "collect_specialist_task"
                };
                let mut interleaved = false;
                let probe = crate::delegation_service::set_managed_observation_probe({
                    let scene = Rc::clone(&scene);
                    let counts = Rc::clone(&counts);
                    move |observed, count| {
                        if observed != operation {
                            return;
                        }
                        if let Some(count) = count {
                            counts.borrow_mut().push(count);
                            return;
                        }
                        if interleaved {
                            return;
                        }
                        interleaved = true;
                        if writer_changes {
                            scene.member.accept_write_task("active-during-observation");
                            writers(&scene.member)
                                .transact(|record| {
                                    let transaction = Uuid::now_v7();
                                    record.prepare_release(scene.member.member_ref, transaction)?;
                                    record.block_unknown(transaction);
                                    Ok(())
                                })
                                .unwrap();
                        } else {
                            scene
                                .member
                                .store()
                                .transact(|transaction| {
                                    assert!(crate::orchestration::settle_successor_task_result(
                                        transaction,
                                        scene.member.session_id,
                                        second.unwrap(),
                                        "failed",
                                        Some("TURN_FAILED"),
                                        None,
                                        unix_time_ms_semantic()?
                                    )?);
                                    Ok(())
                                })
                                .unwrap();
                        }
                    }
                });
                if identity {
                    assert_eq!(
                        scene.identity(first).unwrap_err().code,
                        "DISPOSITION_NOT_IDLE"
                    );
                } else {
                    let observed = scene.collect(first).unwrap();
                    assert_eq!(observed.disposition.dispatching, 1);
                    assert_eq!(observed.disposition.cleanup_pending, writer_changes);
                }
                drop(probe);
                assert_eq!(
                    *counts.borrow(),
                    if writer_changes { vec![0, 1] } else { vec![1] }
                );
                let latest = crate::orchestration::successor_member_quiescence(
                    scene.member.store().connection(),
                    &scene.member.view.workspace_id,
                    scene.member.session_id,
                    scene.member.member_ref,
                )
                .unwrap();
                assert_eq!(latest.dispatching, u64::from(writer_changes));
            }
        }
    }

    fn scheduler_idle_crash_scene() -> (
        Assignment,
        crate::scheduler::Actor,
        crate::worker::WorkerRuntimeRecord,
    ) {
        let scene = Assignment::new();
        let worker = ScriptedWorker::start_member_with_witness(
            &scene.member.view,
            &scene.member.state_root,
            &scene.member.manifest,
            0,
            true,
        );
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(scene.member.session_id),
            run: scene.member.member_ref,
        };
        let snapshot =
            crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
        let runtime = snapshot.runtime_record.clone().unwrap();
        assert_eq!(
            crate::worker::classify_worker_identity(&runtime),
            crate::worker::ProcessIdentityVerdict::Match
        );
        scene
            .member
            .store()
            .transact(|tx| {
                crate::scheduler::observe_actor(
                    tx,
                    actor,
                    snapshot.stamp.run_state_revision,
                    true,
                    crate::scheduler::now_ms()?,
                )?;
                tx.execute(
                    "UPDATE brokered_members SET actor_residency='resident' WHERE run_id=?1",
                    [actor.run.to_string()],
                )
                .unwrap();
                Ok(())
            })
            .unwrap();
        assert!(worker.calls.lock().unwrap().is_empty());
        // Drop reaps only this fixture's witnessed process and sockets. Its
        // retained locator now supplies a real kernel absence observation.
        drop(worker);
        assert_eq!(
            crate::worker::classify_worker_identity(&runtime),
            crate::worker::ProcessIdentityVerdict::Absent
        );
        (scene, actor, runtime)
    }

    #[test]
    fn scheduler_idle_crash_and_restored_recovery_converge_once() {
        for restored in 0..3 {
            let (scene, actor, runtime) = scheduler_idle_crash_scene();
            let before =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            let mut store = scene.member.store();
            let operation = if restored == 0 {
                None
            } else {
                Some(
                    store
                        .transact(|tx| {
                            crate::scheduler::begin_idle_recovery(
                                tx,
                                actor,
                                &serde_json::to_string(&ActorExecutionIdentity::capture(&before)?)
                                    .unwrap(),
                                crate::scheduler::now_ms()?,
                            )
                        })
                        .unwrap(),
                )
            };
            if restored == 2 {
                // Crash after exact physical retirement but before the SQLite
                // outcome: restart must consume the matching absence proof.
                retire_absent_actor_runtime(&scene.member.state_root, &runtime).unwrap();
            }
            drop(store);
            schedule_actor(&scene.member.view, &scene.member.state_root, actor).unwrap();
            let after =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            assert_eq!(
                serde_json::to_value(&after.manifest).unwrap(),
                serde_json::to_value(&before.manifest).unwrap()
            );
            assert_eq!(after.projection.lifecycle, RunLifecycle::Idle);
            assert_eq!(
                after.projection.run_generation,
                before.projection.run_generation
            );
            assert_eq!(after.projection.thread_id, before.projection.thread_id);
            assert!(after.runtime_record.is_none());
            assert!(actor_absence_matches(&scene.member.state_root, &runtime).unwrap());
            let store = scene.member.store();
            let (recorded, state): (String, String) = store
                .connection()
                .query_row(
                    "SELECT operation_id,state FROM scheduler_operations WHERE target_run_id=?1",
                    [actor.run.to_string()],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .unwrap();
            if let Some(operation) = operation {
                assert_eq!(recorded, operation.to_string());
            }
            assert_eq!(state, "passivated");
            assert_eq!(
                crate::scheduler::residency(store.connection(), actor).unwrap(),
                "passivated"
            );
            drop(store);
            schedule_actor(&scene.member.view, &scene.member.state_root, actor).unwrap();
            let store = scene.member.store();
            let count: u64 = store
                .connection()
                .query_row(
                    "SELECT COUNT(*) FROM orchestration_events WHERE session_id=?1 AND kind='actor_idle_crash_reconciled'",
                    [scene.member.session_id.to_string()],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(count, 1);
        }
    }

    #[test]
    fn scheduler_idle_crash_preserves_in_flight_and_changed_recovery_captures() {
        for blocked in ["in-flight", "configuration", "generation"] {
            let (scene, actor, runtime) = scheduler_idle_crash_scene();
            let before =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            let mut store = scene.member.store();
            if blocked == "in-flight" {
                let mut task = crate::delegation_service::fixture_task();
                task.expected_output = "complete_result".into();
                crate::delegation_service::queue_specialist_task(
                    &scene.scope(),
                    &scene.context(),
                    &crate::caller_scope::fixture(3),
                    &super::successor_fixture::AcceptingPort,
                    crate::delegation_service::AssignSpecialistTask {
                        member_ref: actor.run,
                        task,
                        execution_intent: "read_only",
                        target: None,
                        deadline_seconds: 600,
                        expected_revision: None,
                    },
                    1,
                )
                .unwrap();
                store
                    .transact(|tx| {
                        let now = crate::scheduler::now_ms()?;
                        let permit =
                            crate::scheduler::claim(tx, actor.owner, actor.run, now)?.unwrap();
                        crate::scheduler::prepare_dispatch(tx, &permit, now)?;
                        crate::scheduler::finish_dispatch(
                            tx,
                            &permit,
                            &crate::delegation_service::MemberDispatchOutcome::Uncertain {
                                code: "TRANSPORT_FAILURE".into(),
                                message: "Fixture retains unknown acceptance.".into(),
                            },
                            now,
                        )
                    })
                    .unwrap();
            } else {
                let mut captured = ActorExecutionIdentity::capture(&before).unwrap();
                if blocked == "configuration" {
                    captured.configuration = "0".repeat(64);
                } else {
                    captured.generation += 1;
                }
                store
                    .transact(|tx| {
                        crate::scheduler::begin_idle_recovery(
                            tx,
                            actor,
                            &serde_json::to_string(&captured).unwrap(),
                            crate::scheduler::now_ms()?,
                        )
                    })
                    .unwrap();
            }
            drop(store);
            let error =
                schedule_actor(&scene.member.view, &scene.member.state_root, actor).unwrap_err();
            assert_eq!(
                error.details["reason"],
                if blocked == "in-flight" {
                    "resident_generation_unverified"
                } else {
                    "actor_recovery_identity_changed"
                },
                "{blocked}"
            );
            let after =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            assert_eq!(after.runtime_record.as_ref(), Some(&runtime));
            assert!(!actor_absence_matches(&scene.member.state_root, &runtime).unwrap());
            let store = scene.member.store();
            assert_eq!(
                crate::scheduler::residency(store.connection(), actor).unwrap(),
                if blocked == "in-flight" {
                    "resident"
                } else {
                    "recovering"
                }
            );
            assert_eq!(
                store.connection().query_row(
                    "SELECT COUNT(*) FROM orchestration_events WHERE session_id=?1 AND kind='actor_idle_crash_reconciled'",
                    [scene.member.session_id.to_string()], |row| row.get::<_, u64>(0)
                ).unwrap(),
                0
            );
        }
    }

    #[test]
    fn scheduler_expired_passivation_preparation_is_distinct_from_a_crossed_fence() {
        for fenced in [false, true] {
            let (scene, actor, runtime) = scheduler_idle_crash_scene();
            let before =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            let operation = Uuid::now_v7();
            scene.member.store().transact(|tx| {
                tx.execute(
                    "UPDATE scheduler_actors SET operation_id=?2,operation_kind='passivation',lease_until_ms=1 WHERE target_run_id=?1",
                    rusqlite::params![actor.run.to_string(), operation.to_string()]
                ).unwrap();
                crate::scheduler::capture_operation(
                    tx, actor, operation,
                    &serde_json::to_string(&ActorExecutionIdentity::capture(&before)?).unwrap(),
                    crate::scheduler::now_ms()?
                )?;
                if fenced {
                    // Model the committed Worker fence at the crash boundary.
                    tx.execute("UPDATE brokered_members SET actor_residency='passivating' WHERE run_id=?1",[actor.run.to_string()]).unwrap();
                }
                Ok(())
            }).unwrap();
            schedule_actor(&scene.member.view, &scene.member.state_root, actor).unwrap();
            let store = scene.member.store();
            let state: String = store
                .connection()
                .query_row(
                    "SELECT state FROM scheduler_operations WHERE operation_id=?1",
                    [operation.to_string()],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(state, if fenced { "passivated" } else { "not_fenced" });
            assert_eq!(
                crate::scheduler::residency(store.connection(), actor).unwrap(),
                if fenced { "passivated" } else { "resident" }
            );
            let after =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            assert_eq!(after.runtime_record.is_none(), fenced);
            assert_eq!(
                actor_absence_matches(&scene.member.state_root, &runtime).unwrap(),
                fenced
            );
        }
    }

    fn captured_activation(
        scene: &Assignment,
        deadline_seconds: u64,
    ) -> (
        crate::scheduler::Actor,
        crate::scheduler::AcceptedWork,
        Uuid,
        ActorExecutionIdentity,
    ) {
        let mut task = crate::delegation_service::fixture_task();
        task.expected_output = "complete_result".into();
        crate::delegation_service::queue_specialist_task(
            &scene.scope(),
            &scene.context(),
            &crate::caller_scope::fixture(3),
            &super::successor_fixture::AcceptingPort,
            crate::delegation_service::AssignSpecialistTask {
                member_ref: scene.member.member_ref,
                task,
                execution_intent: "canonical_workspace_write",
                target: None,
                deadline_seconds,
                expected_revision: None,
            },
            1,
        )
        .unwrap();
        let actor = crate::scheduler::Actor {
            owner: crate::assignment_queue::Owner::Managed(scene.member.session_id),
            run: scene.member.member_ref,
        };
        let snapshot =
            crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
        let mut store = scene.member.store();
        let now = crate::scheduler::now_ms().unwrap();
        let permit = store
            .transact(|tx| {
                crate::scheduler::observe_actor(
                    tx,
                    actor,
                    snapshot.stamp.run_state_revision,
                    true,
                    now,
                )?;
                tx.execute(
                    "UPDATE brokered_members SET actor_residency='unstarted' WHERE run_id=?1",
                    [actor.run.to_string()],
                )
                .unwrap();
                crate::scheduler::claim(tx, actor.owner, actor.run, now)
            })
            .unwrap()
            .unwrap();
        let mut captured = ActorExecutionIdentity::capture(&snapshot).unwrap();
        captured.writer_acquire = Some(ActorWriterAcquire {
            transaction_id: Uuid::now_v7(),
            previous_generation: snapshot.writer.writer_generation,
            previous_revision: snapshot.writer.authority_revision,
            work: permit.clone(),
        });
        let operation = store
            .transact(|tx| {
                let operation = crate::scheduler::begin_activation(tx, actor, now)?;
                crate::scheduler::capture_operation(
                    tx,
                    actor,
                    operation,
                    &serde_json::to_string(&captured).unwrap(),
                    now,
                )?;
                Ok(operation)
            })
            .unwrap();
        (actor, permit, operation, captured)
    }

    #[test]
    fn scheduler_failed_activation_requires_the_original_acquisition_and_release_guards() {
        for restart in [false, true] {
            let scene = Assignment::new();
            let worker = ScriptedWorker::start_member_with_witness(
                &scene.member.view,
                &scene.member.state_root,
                &scene.member.manifest,
                0,
                true,
            );
            let (actor, permit, operation, captured) = captured_activation(&scene, 600);
            let acquisition = captured.writer_acquire.as_ref().unwrap();
            let holder = crate::writer::WriterStore::holder(
                actor.run,
                scene.member.manifest.profile.profile_name.clone(),
                &scene.member.manifest.controller,
                1,
                scene.member.manifest.profile.initial_server_key.clone(),
                scene
                    .member
                    .manifest
                    .profile_capability_snapshot
                    .server_epoch,
                Some("thread-1".into()),
                RunLifecycle::Idle,
            );
            writers(&scene.member)
                .transact(|record| {
                    let (_, generation) =
                        record.prepare_acquire(actor.run, holder, acquisition.transaction_id)?;
                    record.commit_acquire(acquisition.transaction_id, generation)
                })
                .unwrap();
            let acquired = writers(&scene.member).load().unwrap();
            append_policy(
                &scene.member.state_root,
                actor.run,
                AuditKind::WriterAcquired,
                acquisition.transaction_id,
                true,
                acquired.writer_generation,
            );
            let snapshot =
                crate::snapshot::RunSnapshot::load(&scene.member.state_root, actor.run, 0).unwrap();
            let (_, records) =
                observe_run_ledger(&scene.member.state_root, actor.run, true).unwrap();
            prove_activation_writer(&captured, &snapshot, records.records()).unwrap();
            let mut changed = snapshot.clone();
            changed.writer.writer_generation += 1;
            assert!(prove_activation_writer(&captured, &changed, records.records()).is_err());
            let mut changed = snapshot.clone();
            changed.writer.holder.as_mut().unwrap().run_id = Uuid::now_v7();
            assert!(prove_activation_writer(&captured, &changed, records.records()).is_err());
            let mut changed = snapshot.clone();
            changed.writer.state = crate::writer::WriterAuthorityState::BlockedUnknown;
            assert!(prove_activation_writer(&captured, &changed, records.records()).is_err());
            let mut changed = snapshot.clone();
            changed.runtime_record = None;
            assert!(prove_activation_writer(&captured, &changed, records.records()).is_err());
            let mut changed = snapshot.clone();
            changed.captured_effective_policy.verification =
                crate::domain::PolicyVerification::Unverified;
            assert!(prove_activation_writer(&captured, &changed, records.records()).is_err());
            let mut changed: ActorExecutionIdentity =
                serde_json::from_str(&serde_json::to_string(&captured).unwrap()).unwrap();
            changed.writer_acquire.as_mut().unwrap().transaction_id = Uuid::now_v7();
            assert!(prove_activation_writer(&changed, &snapshot, records.records()).is_err());
            let mut duplicate = records.records().to_vec();
            duplicate.push(
                duplicate
                    .iter()
                    .find(|r| r.kind() == AuditKind::WriterAcquired)
                    .unwrap()
                    .clone(),
            );
            assert!(prove_activation_writer(&captured, &snapshot, &duplicate).is_err());
            let lifecycle = crate::worker::RunLifecycleLease::acquire(
                &scene.member.state_root,
                &scene.member.view.workspace_id,
                actor.run,
                1,
            )
            .unwrap();
            let mut store = scene.member.store();
            let until: i64 = store
                .connection()
                .query_row(
                    "SELECT lease_until_ms FROM scheduler_actors WHERE target_run_id=?1",
                    [actor.run.to_string()],
                    |r| r.get(0),
                )
                .unwrap();
            store
                .transact(|tx| {
                    crate::scheduler::finish_activation(
                        tx,
                        actor,
                        operation,
                        restart,
                        if restart {
                            until
                        } else {
                            crate::scheduler::now_ms()?
                        },
                    )
                })
                .unwrap();
            let recovered = if restart {
                serde_json::from_str(
                    &crate::scheduler::failed_activation_capture(
                        store.connection(),
                        actor,
                        &operation.to_string(),
                    )
                    .unwrap(),
                )
                .unwrap()
            } else {
                captured
            };
            // Ready recognition acquired nothing: a preexisting Writer must
            // never enter compensation merely because activation failed.
            let mut no_acquisition: ActorExecutionIdentity =
                serde_json::from_str(&serde_json::to_string(&recovered).unwrap()).unwrap();
            no_acquisition.writer_acquire = None;
            compensate_activation_writer(
                &scene.member.view,
                &scene.member.state_root,
                &mut store,
                actor,
                operation,
                &no_acquisition,
                &lifecycle,
            )
            .unwrap();
            assert_eq!(writers(&scene.member).load().unwrap(), acquired);
            // This fixture has no native Thread registration. The positive
            // ownership proof cannot bypass ordinary qualified release fences.
            assert!(
                compensate_activation_writer(
                    &scene.member.view,
                    &scene.member.state_root,
                    &mut store,
                    actor,
                    operation,
                    &recovered,
                    &lifecycle,
                )
                .is_err()
            );
            assert_eq!(writers(&scene.member).load().unwrap(), acquired);
            assert_eq!(
                crate::scheduler::residency(store.connection(), actor).unwrap(),
                "unavailable"
            );
            assert_eq!(
                crate::scheduler::candidates(store.connection(), actor.owner, actor.run)
                    .unwrap()
                    .len(),
                1
            );
            assert_eq!(
                crate::orchestration::successor_task(
                    store.connection(),
                    scene.member.session_id,
                    permit.work
                )
                .unwrap()
                .unwrap()
                .state,
                "queued"
            );
            assert!(worker.calls.lock().unwrap().is_empty());
            // Even after the acceptance deadline, expiry is non-dispatching;
            // the following visit attempts existing terminal Writer cleanup.
            let retained = crate::scheduler::retained_task(
                &store,
                &permit,
                &scene.member.view.workspace_id,
                &scene.member.state_root,
            )
            .unwrap();
            expire_queued_tasks(
                &scene.member.view,
                &scene.member.state_root,
                actor,
                retained.deadline_ms,
            )
            .unwrap();
            assert!(
                reconcile_scheduler_writer(
                    &scene.member.view,
                    &scene.member.state_root,
                    actor,
                    &lifecycle
                )
                .is_err()
            );
            let phase: String = store
                .connection()
                .query_row(
                    "SELECT phase FROM scheduler_claims WHERE claim_id=?1",
                    [permit.claim.to_string()],
                    |r| r.get(0),
                )
                .unwrap();
            assert_eq!(phase, "accepted");
            assert_eq!(writers(&scene.member).load().unwrap(), acquired);
            assert_eq!(
                crate::orchestration::successor_task(
                    store.connection(),
                    scene.member.session_id,
                    permit.work
                )
                .unwrap()
                .unwrap()
                .state,
                "expired"
            );
            assert!(worker.calls.lock().unwrap().is_empty());
        }
    }

    #[test]
    fn initial_writer_reuse_keeps_read_terminal_and_transition_cleanup() {
        let scene = Assignment::new();
        let worker = ScriptedWorker::start(&scene, 0);
        let carrier = broker(&scene.member);
        hold(
            &scene.member,
            scene.member.member_ref,
            &scene.member.manifest.controller,
        );
        let writer = writers(&scene.member);
        let initial = writer.load().unwrap();
        append_policy(
            &scene.member.state_root,
            scene.member.member_ref,
            AuditKind::WriterAcquired,
            Uuid::now_v7(),
            true,
            initial.writer_generation,
        );
        let cleanup = |write| {
            release_stale_member_writer(
                &scene.member.view,
                &scene.member.state_root,
                scene.member.member_ref,
                scene.member.owner(),
                &carrier,
                write,
                None,
            )
        };
        cleanup(true).unwrap();
        assert_eq!(writer.load().unwrap(), initial);
        assert!(worker.calls.lock().unwrap().is_empty());

        // Read-only dispatch and pending or terminal cleanup still require release.
        assert_eq!(cleanup(false).unwrap_err().code, "RUNTIME_PATH_COLLISION");
        assert_eq!(writer.load().unwrap(), initial);
        let transaction = Uuid::now_v7();
        writer
            .transact(|record| record.prepare_release(scene.member.member_ref, transaction))
            .unwrap();
        let releasing = writer.load().unwrap();
        assert_eq!(cleanup(true).unwrap_err().code, "RUNTIME_PATH_COLLISION");
        assert_eq!(writer.load().unwrap(), releasing);
        writer
            .transact(|record| {
                record.rollback_release(transaction);
                Ok(())
            })
            .unwrap();
        scene.member.publish_terminal_turn(
            "prior-turn",
            "completed",
            "prior result",
            RunLifecycle::Idle,
        );
        let retained = writer.load().unwrap();
        assert_eq!(cleanup(true).unwrap_err().code, "RUNTIME_PATH_COLLISION");
        assert_eq!(writer.load().unwrap(), retained);
        assert!(worker.calls.lock().unwrap().is_empty());
    }

    #[test]
    fn managed_release_failure_after_publication_does_not_resettle() {
        let scene = Assignment::new();
        let task = running(&scene);
        publish_terminal(&scene).unwrap();
        let broker = crate::orchestration::BrokerCredential::load(
            &scene
                .member
                .state_root
                .join("orchestration/broker-credentials"),
            DarwinSystem.current_uid(),
            scene.member.member_ref,
        )
        .unwrap();
        let carrier = broker.controller_carrier().unwrap();
        let settle = || {
            settle_successor_task(
                &scene.member.view,
                &scene.member.state_root,
                scene.member.owner(),
                scene.member.member_ref,
                task,
                "canonical_workspace_write",
                Some(&carrier),
                None,
            )
        };
        let before = writers(&scene.member).load().unwrap();
        assert!(before.generation_release.is_none());
        // Direct terminal publication leaves no native Thread binding in this fixture.
        assert!(settle().is_err());
        let bytes = scene.member.complete_result_bytes(task).unwrap();
        assert_eq!(scene.member.workload_revision(), 1);
        assert_eq!(writers(&scene.member).load().unwrap(), before);
        assert!(scene.collect(task).unwrap().disposition.cleanup_pending);
        assert_eq!(
            settle().unwrap(),
            crate::delegation_service::MemberSettlement::Terminal
        );
        resettle_member_tasks(
            &scene.member.state_root,
            scene.member.member_ref,
            scene.member.owner(),
        )
        .unwrap();
        assert_eq!(scene.member.complete_result_bytes(task).unwrap(), bytes);
        assert_eq!(scene.member.workload_revision(), 1);
    }

    #[test]
    fn current_unwitnessed_and_historical_unqualified_release_preserve_their_guards() {
        for historical in [false, true] {
            let scene = if historical {
                Assignment::with_member(ManagedMember::historical_writable())
            } else {
                Assignment::new()
            };
            let path =
                run_root(&scene.member.state_root, scene.member.member_ref).join("manifest.json");
            let before = std::fs::read(&path).unwrap();
            let binding = scene
                .member
                .manifest
                .global_profile_binding
                .as_ref()
                .unwrap();
            assert_eq!(binding.caller_workspace_supported(), !historical);
            let worker = ScriptedWorker::start(&scene, 0);
            let carrier = broker(&scene.member);
            hold(
                &scene.member,
                scene.member.member_ref,
                &scene.member.manifest.controller,
            );
            let generation = writers(&scene.member).load().unwrap().writer_generation;
            append_policy(
                &scene.member.state_root,
                scene.member.member_ref,
                AuditKind::WriterAcquired,
                Uuid::now_v7(),
                true,
                generation,
            );
            let head = durable_head(&scene.member.state_root, scene.member.member_ref).unwrap();
            let writer_before = writers(&scene.member).load().unwrap();
            assert!(writer_before.generation_release.is_none());
            let error = release_writer_authorized(
                &scene.member.view,
                &scene.member.state_root,
                scene.member.member_ref,
                &carrier,
                None,
                Some(head),
            )
            .unwrap_err();
            assert_eq!(error.code, "RUNTIME_PATH_COLLISION");
            let (_, ledger) =
                observe_caller_ledger(&scene.member.state_root, scene.member.member_ref).unwrap();
            let writer_after = writers(&scene.member).load().unwrap();
            let calls = worker.calls.lock().unwrap();
            let released = ledger
                .records()
                .iter()
                .any(|record| record.kind() == AuditKind::WriterReleased);
            if historical {
                assert_eq!(
                    writer_after.state,
                    crate::writer::WriterAuthorityState::BlockedUnknown
                );
                assert!(calls.iter().any(|call| call == "run.release_write"));
                assert!(released);
            } else {
                assert_eq!(writer_after, writer_before);
                assert!(writer_after.generation_release.is_none());
                assert!(calls.is_empty());
                assert!(!released);
            }
            assert_eq!(std::fs::read(&path).unwrap(), before);
        }
    }

